seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=''.join(comp[c] for c in reversed(seq))
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
ct={}; i=0
for a in bases:
    for b in bases:
        for c in bases:
            ct[a+b+c]=aas[i]; i+=1

def orfs(s,label,minaa=50):
    out=[]
    for f in range(3):
        i=f
        # find stop-to-stop segments, then ATGs within
        t=''.join(ct.get(s[i:i+3],'X') for i in range(f,len(s)-2,3))
        j=0
        segs=[]
        while j<len(t):
            if t[j]=='*': j+=1; continue
            k=j
            while k<len(t) and t[k]!='*': k+=1
            segs.append((j,k)); j=k
        for (j,k) in segs:
            for m in range(j,k):
                if t[m]=='M':
                    L=k-m
                    if L>=minaa:
                        # coords
                        if label=='fwd':
                            st=m*3+f+1; en=k*3+f
                        else:
                            st=len(seq)-(k*3+f); en=len(seq)-(m*3+f)-1
                        out.append((L,st,en,t[m:m+45]))
                    break
    return out

for lab,s in [('fwd',seq),('rev',rc)]:
